let state={saved:[],progress:{'sanft-01':0.38,'morgen-01':0.17},history:['sanft-01','morgen-01'],mood:'',name:'',goal:3,reminders:false,time:'08:00',read:false,program:''};
try{const s=JSON.parse(localStorage.getItem('andavita_demo_v1'));if(s&&typeof s==='object')state={...state,...s};}catch{}
state.saved=state.saved.filter(id=>courses.some(c=>c.id===id));state.history=state.history.filter(id=>courses.some(c=>c.id===id));if(!state.history.length)state.history=['sanft-01','morgen-01'];
state.saved=state.saved.filter(id=>courses.some(c=>c.id===id));state.history=state.history.filter(id=>courses.some(c=>c.id===id));if(!state.history.length)state.history=['sanft-01','morgen-01'];
let route='home',libraryTab='saved',query='',category='Alle Themen',duration='all',teacher='all',toastTimer,player=null,playerTimer;
function persist(){try{localStorage.setItem('andavita_demo_v1',JSON.stringify(state));}catch{toast('Dein Browser erlaubt kein Speichern. Änderungen gelten für diese Sitzung.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3300);}
function nav(){const items=[['home','home','Für dich'],['discover','compass','Entdecken'],['programs','layers','Programme'],['library','heart','Meine Sammlung']];$('#nav').innerHTML=items.map(([r,i,n])=>`<a class="nav-item ${route===r?'active':''}" href="#${r}" ${route===r?'aria-current="page"':''}>${icon(i)}<span>${n}</span>${r==='library'&&state.saved.length?`<span class="nav-count">${state.saved.length}</span>`:''}</a>`).join('');$('.unread-dot').hidden=state.read;}
function courseCard(c,progress=false){const saved=state.saved.includes(c.id);return `<article class="course"><button class="course-image" data-action="play" data-id="${c.id}" aria-label="${c.title} öffnen"><img src="assets/${c.image}.jpg" alt="${c.image==='strength'?'Mann übt mit einem Stuhl im hellen Studio':c.image==='rest'?'Frau sitzt entspannt im hellen Studio':'Frau bei einer sanften Yoga-Dehnung'}" loading="lazy"><span class="course-tag">${c.label}</span><span class="course-play">${icon('play')}</span><span class="duration">${durationText(c)}</span></button><button class="save-button ${saved?'saved':''}" data-action="save" data-id="${c.id}" aria-label="${c.title}: ${saved?'aus Merkliste entfernen':'merken'}" aria-pressed="${saved}">${icon('heart')}</button><div class="course-info"><div class="category">${c.category}</div><h3><button data-action="play" data-id="${c.id}">${c.title}</button></h3><div class="course-meta"><span>${c.type} · mit ${c.teacher}</span><span>${progress&&state.progress[c.id]&&c.duration?`${Math.max(1,Math.ceil(c.duration*(1-state.progress[c.id])))} Min übrig` : c.level}</span></div>${progress?`<div class="progress-line" aria-label="${Math.round((state.progress[c.id]||0)*100)} Prozent angesehen"><span style="width:${Math.round((state.progress[c.id]||0)*100)}%"></span></div>`:''}</div></article>`;}
function weekCard(){return `<aside class="week-card"><div class="week-top"><span class="eyebrow">DEIN RHYTHMUS</span>${icon('calendar')}</div><h2>Ein guter Anfang.</h2><p>Du machst dir Raum für dich.</p><div class="week-days">${['M','D','M','D','F','S','S'].map((d,i)=>`<div class="day ${i===0||i===2?'done':i===3?'today':''}"><label>${d}</label><span>${i===0||i===2?'✓':i===3?'17':'·'}</span></div>`).join('')}</div><div class="week-progress"><span style="width:${Math.min(100,2/state.goal*100)}%"></span></div><div class="week-stats"><b>2 von ${state.goal} Momenten</b><span>Beispielwoche</span></div><button class="week-link" data-action="week">Deine Woche ansehen ${icon('arrow')}</button></aside>`;}
function home(){const rec=courses.find(c=>c.id===(state.mood==='Ruhe finden'?'reset-02':state.mood==='Kraft sammeln'?'ruecken-03':state.mood==='Beweglich bleiben'?'sanft-02':'morgen-01'));const others=(state.mood==='Ruhe finden'?['reset-03','schlaf-01','schlaf-02']:state.mood==='Kraft sammeln'?['ruecken-01','ruecken-03','sanft-03']:['sanft-01','reset-02','ruecken-02']).map(id=>courses.find(c=>c.id===id));return `<section class="welcome"><div><div class="eyebrow">${icon('sun')} DEIN MOMENT ZÄHLT</div><h1>Schön, dass du da bist${state.name?', '+escapeHTML(state.name):''}.</h1><p>Bewegung, die dir guttut. Ruhe, die dich weiterbringt.</p></div><span class="date-label">Ein neuer Tag. Dein eigenes Tempo.</span></section><div class="hero-grid"><section class="hero"><img src="assets/${rec.image}.jpg" alt="Ruhige Bewegung in einem sonnigen Studio"><div class="hero-copy"><span class="pill">${icon('spark')} FÜR DICH AUSGEWÄHLT</span><h2>${state.mood==='Ruhe finden'?'Einatmen.<br>Ausatmen.<br>Bei dir sein.':state.mood==='Kraft sammeln'?'Neue Kraft.<br>Ganz in deinem<br>Tempo.':'Dein Tag.<br>Dein Tempo.<br>Dein Moment.'}</h2><p>${rec.title}.</p><div class="hero-meta"><span>${durationText(rec)}</span><span>·</span><span>${rec.level}</span><span>·</span><span>mit ${rec.teacher}</span></div><button class="btn" data-action="play" data-id="${rec.id}">${icon('play')} Jetzt beginnen</button></div><div class="hero-credit">${icon('leaf')} Gut zu dir. Jeden Tag.</div></section>${weekCard()}</div><section class="growing-note"><span class="growing-icon">${icon('spark')}</span><div><strong>Jeden Monat neue Inhalte für dich.</strong><p>Dein Start: 5 Serien mit 34 Videos. Monatlich kommen neue Inhalte dazu – in deiner Mitgliedschaft inklusive. Entdecke schon jetzt die kommenden Kursreihen.</p></div><button class="text-link" data-action="notifications">Neuigkeiten ${icon('arrow')}</button></section><section class="mood-row" aria-label="Empfehlungen anpassen"><h2 class="mood-title">Was brauchst du heute?</h2><div class="mood-options">${[['Energie tanken','sun'],['Ruhe finden','moon'],['Beweglich bleiben','wind'],['Kraft sammeln','leaf']].map(([m,i])=>`<button class="chip ${state.mood===m?'selected':''}" data-action="mood" data-mood="${m}" aria-pressed="${state.mood===m}">${icon(i)}${m}</button>`).join('')}</div></section><section><div class="section-head"><div><h2>${state.mood?'Passend zu deinem Gefühl':'Deine nächsten Wohlfühlmomente'}</h2><p>${state.mood?'Eine Auswahl für „'+state.mood+'“.':'Ein bisschen Kraft. Ein tiefer Atemzug. Ein gutes Gefühl.'}</p></div><a class="text-link" href="#discover">Alle entdecken ${icon('arrow')}</a></div><div class="cards home-cards">${others.map(c=>courseCard(c)).join('')}</div></section><section><div class="section-head"><div><h2>Hier kannst du weitermachen</h2><p>Dein letzter Moment ist nur einen Klick entfernt.</p></div><button class="text-link" data-action="history">Zuletzt gesehen ${icon('arrow')}</button></div><div class="cards home-cards">${state.history.slice(0,3).map(id=>courses.find(c=>c.id===id)).filter(Boolean).map(c=>courseCard(c,true)).join('')}</div></section><section><div class="section-head"><h2>Entdecke, was dich bewegt</h2><a href="#discover" class="text-link">Alle Themen ${icon('arrow')}</a></div><div class="topics">${[['Morgen & Energie','sun'],['Einstieg','leaf'],['Knochen & Gelenke','wind'],['Innere Balance','leaf']].map(([n,i])=>`<button class="topic" data-action="topic" data-topic="${n}">${icon(i)}<span>${n}${icon('arrow')}</span></button>`).join('')}</div></section><section class="bottom-band"><img src="assets/flower.svg" alt=""><div><h2>Kleine Schritte. Ein neues Körpergefühl.</h2><p>Finde mit unseren Programmen deinen eigenen Rhythmus.</p></div><a class="btn gold" href="#programs">Programme entdecken ${icon('arrow')}</a></section>`;}
function discover(){const list=courses.filter(c=>(category==='Alle Themen'||c.category===category)&&(duration==='all'||(c.duration!==null&&c.duration<=Number(duration)))&&(teacher==='all'||c.teacher===teacher)&&(`${c.title} ${c.category} ${c.type} ${c.teacher}`.toLowerCase().includes(query.toLowerCase())));return `<div class="page-intro"><span class="eyebrow">DEIN KÖRPER. DEINE AUSWAHL.</span><h1>Wonach ist dir heute?</h1><p>Vom ersten Strecken bis zum letzten tiefen Atemzug.</p><div class="growing-note"><span class="growing-icon">${icon('spark')}</span><div><strong>Ein Anfang, der mit dir wächst.</strong><p>Starte mit 5 Serien und 34 Videos. Monatlich kommen neue Inhalte hinzu – in deiner Mitgliedschaft inklusive.</p></div></div></div><form class="filters" id="filters"><input type="search" id="course-query" aria-label="Kurse durchsuchen" placeholder="Kurs, Thema oder Name suchen" value="${escapeHTML(query)}"><select id="category-filter" aria-label="Thema"><option>Alle Themen</option>${[...new Set(courses.map(c=>c.category))].map(t=>`<option ${category===t?'selected':''}>${t}</option>`).join('')}</select><select id="duration-filter" aria-label="Dauer">${[['all','Jede Dauer'],['10','Bis 10 Minuten'],['20','Bis 20 Minuten'],['30','Bis 30 Minuten']].map(([v,t])=>`<option value="${v}" ${duration===v?'selected':''}>${t}</option>`).join('')}</select><select id="teacher-filter" aria-label="Trainerin oder Trainer">${[['all','Alle Trainerinnen und Trainer'],['Nina','Mit Nina'],['Simone','Mit Simone']].map(([v,t])=>`<option value="${v}" ${teacher===v?'selected':''}>${t}</option>`).join('')}</select></form><div class="result-count" aria-live="polite">${list.length} passende ${list.length===1?'Einheit':'Einheiten'} · Themenvorschau; Einheitentitel vorläufig</div><div class="cards catalogue">${list.length?list.map(c=>courseCard(c)).join(''):`<div class="empty"><h2>Ein bisschen mehr Spielraum?</h2><p>Für diese Auswahl gibt es noch keine Einheit.</p><button class="btn" data-action="reset-filters">Alle Kurse anzeigen</button></div>`}</div>`;}
const programs=[{"id": "sanft", "name": "Sanft starten", "image": "movement", "tag": "ZUM START DABEI", "text": "Atemgrundlagen · Gelenke mobilisieren · Stand und Balance · Sicher auf und von der Matte · Angepasster Sonnengruß · Hüfte · Schultern und Nacken · Rückenbasics · Entspannen · Erste eigene Praxis", "ids": ["sanft-01", "sanft-02", "sanft-03", "sanft-04", "sanft-05", "sanft-06", "sanft-07", "sanft-08", "sanft-09", "sanft-10"], "teacher": "Nina", "duration": null}, {"id": "reset", "name": "Nervensystem-Reset", "image": "rest", "tag": "ZUM START DABEI", "text": "Das Nervensystem kennenlernen · Beruhigende Atmung · Progressive Muskelentspannung · Abendpraxis · Vagus-Übungen · Bodyscan und Autogenes Training · Abendritual", "ids": ["reset-01", "reset-02", "reset-03", "reset-04", "reset-05", "reset-06", "reset-07"], "teacher": "Simone", "duration": null}, {"id": "schlaf", "name": "Besser schlafen", "image": "rest", "tag": "ZUM START DABEI", "text": "Abend-Yoga · Yoga Nidra · kurz · Yoga Nidra · lang · Atemtechniken im Liegen · Schultern und Nacken am Abend", "ids": ["schlaf-01", "schlaf-02", "schlaf-03", "schlaf-04", "schlaf-05"], "teacher": "Simone", "duration": null}, {"id": "morgen", "name": "15-Minuten-Morgenroutine", "image": "movement", "tag": "ZUM START DABEI", "text": "Sanft wach werden · Energie · Rücken mobilisieren · Balance und Fokus · Herz öffnen · Hüfte und Beine · Morgen-Flow", "ids": ["morgen-01", "morgen-02", "morgen-03", "morgen-04", "morgen-05", "morgen-06", "morgen-07"], "teacher": "Nina", "duration": 15}, {"id": "ruecken", "name": "Starker Rücken 50+", "image": "strength", "tag": "ZUM START DABEI", "text": "Haltungscheck · Wirbelsäule mobilisieren · Rückenfreundlich kräftigen · Faszien und Entlastungshaltungen · Rücken-Flow", "ids": ["ruecken-01", "ruecken-02", "ruecken-03", "ruecken-04", "ruecken-05"], "teacher": "Simone", "duration": null}];
const comingPrograms=[{"name": "Balance im Wandel", "teacher": "Nina · 2 Gast-Einheiten mit Simone", "count": "15–18 Videos · Umfang in Abstimmung", "theme": "Wechseljahre & Hormone", "text": "Nervensystem & Balance, Beweglichkeit, Kraft/Muskeln/Knochen, Alltag und Mindset. Simone: Bodyscan/Tiefenentspannung und Becken/Hüfte/Beckenboden."}, {"name": "Knochen-stark", "teacher": "Nina", "count": "7 Videos geplant", "theme": "Knochen & Gelenke", "text": "Aufrichtung, Kraft und Stand – mit Balance, Armen, Schultern und Handgelenken."}, {"name": "Bewegte Pause", "teacher": "Nina", "count": "5 × 10 Minuten geplant", "theme": "Morgen & Energie / Innere Balance", "text": "Bewegung für den Arbeitstag, ohne Umziehen. Drei Einheiten sind vollständig auf dem Stuhl geplant."}, {"name": "Marma-Yoga: Finde deine innere und äußere Balance mit den sechs Spannungsbögen", "teacher": "Simone", "count": "6 Videos geplant", "theme": "Innere Balance", "text": "Körperwahrnehmung, Marma-Punkte, Herzraum, Bauchraum und Abendpraxis."}, {"name": "Meditation lernen", "teacher": "Simone", "count": "7 Videos geplant", "theme": "Innere Balance", "text": "Sitz und Atem, Atem zählen, Bodyscan, Umgang mit Ablenkung und Metta-Basics."}, {"name": "Yoga für einen bewussten und kraftvollen Beckenboden", "teacher": "Simone", "count": "7 Videos geplant", "theme": "Beckenboden", "text": "Anatomie, Wahrnehmung, Aktivierung, Zusammenspiel mit dem Atem und Alltagspraxis."}];
function programPage(){return `<div class="page-intro"><span class="eyebrow">DEIN START MIT ANDAVITA</span><h1>Fünf Serien. Dein Anfang.</h1><p>34 Videos mit Nina und Simone – von deinem ersten Einstieg bis zu deiner Abendroutine.</p></div><div class="program-grid">${programs.map(p=>`<article class="program"><img src="assets/${p.image}.jpg" alt="Illustratives Kursmotiv, kein Portrait der Expertin"><div class="program-body"><span class="eyebrow">${p.tag}</span><h2>${p.name}</h2><p>${p.text}</p><div class="course-meta"><span>${p.ids.length} Videos ${p.duration?'· je 15 Minuten':''}</span><span>Mit ${p.teacher}</span></div><button class="btn" data-action="program" data-id="${p.id}">Serie ansehen ${icon('arrow')}</button></div></article>`).join('')}</div><section><div class="section-head"><div><span class="eyebrow">DAS KOMMT DANACH</span><h2>Mehr Raum für deine Themen.</h2><p>Monatlich neue Inhalte – in deiner Mitgliedschaft inklusive. Diese sechs Serien sind als Nächstes geplant.</p></div></div><div class="program-grid">${comingPrograms.map(p=>`<article class="settings-card"><span class="eyebrow">DEMNÄCHST · ${p.theme}</span><h2>${p.name}</h2><p>${p.text}</p><div class="course-meta"><span>${p.teacher}</span><span>${p.count}</span></div></article>`).join('')}</div></section>`;}
function library(){const ids=libraryTab==='saved'?state.saved:state.history;return `<div class="page-intro"><span class="eyebrow">DEIN PERSÖNLICHER ORT</span><h1>Deine guten Momente.</h1><p>Alles, was du dir merken oder noch einmal erleben möchtest.</p></div><div class="tabs" role="tablist" aria-label="Sammlung"><button role="tab" aria-selected="${libraryTab==='saved'}" class="tab ${libraryTab==='saved'?'selected':''}" data-action="library-tab" data-tab="saved">Merkliste (${state.saved.length})</button><button role="tab" aria-selected="${libraryTab==='history'}" class="tab ${libraryTab==='history'?'selected':''}" data-action="library-tab" data-tab="history">Zuletzt gesehen</button></div><div class="cards catalogue" role="tabpanel">${ids.length?ids.map(id=>courses.find(c=>c.id===id)).filter(Boolean).map(c=>courseCard(c,libraryTab==='history')).join(''):`<div class="empty">${icon('heart')}<h2>Hier ist Platz für deine Lieblingsmomente.</h2><p>Tippe bei einer Einheit auf das Herz. Du findest sie dann hier wieder.</p><a class="btn" href="#discover">Einheiten entdecken ${icon('arrow')}</a></div>`}</div>`;}
function profile(){return `<div class="page-intro"><span class="eyebrow">SO, WIE ES ZU DIR PASST</span><h1>Dein Andavita.</h1><p>Ein kleiner Rahmen für deine ganz persönliche Routine.</p></div><form id="settings-form"><div class="settings-grid"><section class="settings-card"><h2>Schön, dich kennenzulernen.</h2><p>Wie möchtest du angesprochen werden?</p><label class="field">Dein Vorname<input name="name" autocomplete="given-name" maxlength="30" value="${escapeHTML(state.name)}" placeholder="Dein Vorname"></label><h2 style="margin-top:30px">Dein Wochenrhythmus</h2><p>Wie oft möchtest du dir Zeit nehmen? Du kannst dein Ziel jederzeit ändern.</p><label class="field">Momente pro Woche<select name="goal">${[2,3,4,5,6,7].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} Momente</option>`).join('')}</select></label></section><section class="settings-card"><h2>Eine kleine Erinnerung.</h2><p>Lege fest, wann dein Moment in deinen Alltag passt.</p><label class="toggle-row">Erinnerung vormerken<input name="reminders" type="checkbox" ${state.reminders?'checked':''}></label><label class="field">Deine Wunschzeit<input type="time" name="time" value="${escapeHTML(state.time)}" required></label><p class="notice">In dieser Vorschau speichern wir deine Einstellung nur auf diesem Gerät. Push-Nachrichten werden noch nicht versendet.</p><p class="notice">Deine Merkliste, Einstellungen und der Demo-Fortschritt bleiben ebenfalls in diesem Browser. Ein Konto ist für den Entwurf nicht nötig.</p></section></div><div class="modal-actions"><button class="btn" type="submit">Einstellungen speichern ${icon('check')}</button></div></form>`;}
function render(){route=(location.hash.slice(1)||'home').split('?')[0];if(!['home','discover','programs','library','profile'].includes(route))route='home';nav();$('#main').innerHTML=({home,discover,programs:programPage,library,profile}[route])();document.title=`Andavita · ${{home:'Für dich',discover:'Entdecken',programs:'Programme',library:'Meine Sammlung',profile:'Dein Profil'}[route]}`;}
function navigate(r){if(location.hash==='#'+r){render();window.scrollTo(0,0);}else location.hash=r;}
function openModal(title,body,wide=false){const modal=$('#modal');modal.style.maxWidth=wide?'880px':'660px';$('#modal-content').innerHTML=`<div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Schließen">${icon('close')}</button></div>${body}`;if(!modal.open)modal.showModal();}
function closeModal(){stopPlayer();$('#modal').close();}
function save(id){if(!courses.some(c=>c.id===id))return;const saved=state.saved.includes(id);state.saved=saved?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();toast(saved?'Aus deiner Merkliste entfernt.':'Für deinen nächsten Moment gemerkt.');}
function notifications(){openModal('Deine Neuigkeiten',`<div class="modal-body"><span class="demo-label">BEISPIEL-BENACHRICHTIGUNGEN</span><div class="notification-item">${icon('sun')}<div><h3>Ein kleiner Moment wartet auf dich.</h3><p>15 Minuten für deinen Morgen: Entdecke die Morgenroutine mit Nina.</p><button class="text-link" data-action="play" data-id="morgen-01">Einheit ansehen ${icon('arrow')}</button><br><small>Dein Tagesimpuls</small></div></div><div class="notification-item">${icon('layers')}<div><h3>Das ist erst der Anfang.</h3><p>Jeden Monat kommen neue Inhalte dazu – in deiner Mitgliedschaft inklusive. Hier halten wir dich auf dem Laufenden. Entdecke bis dahin „Sanft starten“.</p><button class="text-link" data-action="program" data-id="sanft">Programm entdecken ${icon('arrow')}</button></div></div><div class="modal-actions"><button class="btn light" data-action="mark-read">${state.read?'Alles gelesen':'Alle als gelesen markieren'}</button><button class="btn outline" data-action="settings">Erinnerungen einstellen</button></div></div>`);}
function week(){openModal('Deine Woche. Dein Rhythmus.',`<div class="modal-body"><p class="notice">Beispielwoche: So könnte dein persönlicher Plan aussehen.</p><ul class="plan-list">${[['Mo','Atemgrundlagen','sanft-01','Beispiel'],['Mi','Beruhigende Atmung','reset-02','Beispiel'],['Do','Wirbelsäule mobilisieren','ruecken-02','Idee für heute'],['Sa','Abend-Yoga','schlaf-01','Idee fürs Wochenende']].map(([day,title,id,status])=>`<li><span class="plan-number">${day}</span><div>${title}<small>${status}</small></div><button class="icon-button" data-action="play" data-id="${id}" aria-label="${title} öffnen">${icon('play')}</button></li>`).join('')}</ul><div class="modal-actions"><button class="btn light" data-action="settings">Wochenziel anpassen</button></div></div>`);}
function programDetail(id){const p=programs.find(p=>p.id===id);if(!p)return;openModal(p.name,`<div class="modal-body"><p>${p.text}</p><p class="notice">${p.ids.length} Videos · mit ${p.teacher}. Die Einheitentitel in diesem Entwurf sind aus der Serienübersicht abgeleitet.</p><ul class="plan-list">${p.ids.map((id,i)=>{const c=courses.find(c=>c.id===id);return `<li><span class="plan-number">${i+1}</span><div>${c.title}<small>${durationText(c)} · ${c.teacher}</small></div><button class="icon-button" data-action="play" data-id="${id}" aria-label="${c.title} öffnen">${icon('play')}</button></li>`;}).join('')}</ul><div class="modal-actions"><button class="btn gold" data-action="enroll" data-id="${p.id}">${state.program===p.id?'Erste Einheit öffnen':'Dieses Programm beginnen'} ${icon('arrow')}</button></div></div>`);}
function stopPlayer(){clearInterval(playerTimer);playerTimer=null;if(player){state.progress[player.id]=Math.min(1,player.current/player.total);persist();player=null;}}
function startPlayer(id){const c=courses.find(c=>c.id===id);if(!c)return;stopPlayer();state.history=[id,...state.history.filter(x=>x!==id)];persist();player={id,total:(c.duration||1)*60,current:Math.floor((state.progress[id]||0)*(c.duration||1)*60),playing:false};openModal('Dein Moment mit Andavita',`<div class="player" id="player"><img src="assets/${c.image}.jpg" alt="Kursbild als Player-Vorschau"><span class="player-badge">PLAYER-DEMO · KURSAUFNAHME FOLGT</span><div class="player-overlay"><button class="player-start" data-action="toggle-play" aria-label="Demo abspielen">${icon('play')}</button><span class="player-caption">Nimm dir einen Moment.</span></div><div class="player-controls"><input id="seek" type="range" min="0" max="${player.total}" step="1" value="${player.current}" aria-label="Wiedergabeposition"><div class="control-row"><button class="icon-button" data-action="toggle-play" aria-label="Demo abspielen">${icon('play')}</button><button class="icon-button" data-action="rewind" aria-label="15 Sekunden zurück">${icon('back')}</button><span id="player-time"></span><span class="spacer"></span><span>Vorschau ohne Ton</span><button class="icon-button" data-action="fullscreen" aria-label="Vollbild">${icon('full')}</button></div></div></div><div class="modal-body player-details"><span class="eyebrow">${c.type} · ${c.level} · ${durationText(c)}</span><h3>${c.title}</h3><p>${c.desc}</p><p class="notice">Hier kannst du die Player-Bedienung ausprobieren. Das Bild und der Zeitablauf sind eine Demo; ein angeleitetes Kursvideo wird später hinterlegt.</p><div class="chapters">${[[0,'Ankommen'],[Math.round(player.total*.15),'Deine Praxis'],[Math.round(player.total*.85),'Ruhiger Abschluss']].map(([t,title])=>`<button class="chapter" data-action="chapter" data-time="${t}">${title}<span>${formatTime(t)} ${icon('play')}</span></button>`).join('')}</div></div>`,true);updatePlayer();}
function formatTime(s){return `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;}
function updatePlayer(){if(!player)return;$('#player-time').textContent=`${formatTime(player.current)} / ${formatTime(player.total)}`;$('#seek').value=player.current;document.querySelectorAll('[data-action="toggle-play"]').forEach(b=>{b.innerHTML=icon(player.playing?'pause':'play');b.setAttribute('aria-label',player.playing?'Demo pausieren':'Demo abspielen');});$('.player-caption').textContent=player.current>=player.total?'Ein Moment für dich.':player.playing?(player.current<player.total*.15?'Ankommen. In deinem Tempo.':player.current<player.total*.85?'Raum für deine Bewegung.':'Zeit, nachzuspüren.'):'Nimm dir einen Moment.';}
function togglePlayer(){if(!player)return;player.playing=!player.playing;if(player.current>=player.total)player.current=0;clearInterval(playerTimer);if(player.playing)playerTimer=setInterval(()=>{if(!player)return;player.current++;if(player.current>=player.total){player.current=player.total;player.playing=false;clearInterval(playerTimer);state.progress[player.id]=1;persist();}updatePlayer();},1000);updatePlayer();}
$('#search-icon').innerHTML=icon('search');$('#bell-icon').innerHTML=icon('bell');
$('#search-form').addEventListener('submit',e=>{e.preventDefault();query=$('#global-search').value.trim();category='Alle Themen';navigate('discover');});
window.addEventListener('hashchange',()=>{if($('#modal').open)closeModal();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
$('#modal').addEventListener('close',()=>{stopPlayer();render();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;switch(a){case 'save':save(b.dataset.id);break;case 'play':startPlayer(b.dataset.id);break;case 'close':closeModal();break;case 'mood':state.mood=state.mood===b.dataset.mood?'':b.dataset.mood;persist();render();break;case 'topic':category=b.dataset.topic;query='';duration='all';teacher='all';navigate('discover');break;case 'history':libraryTab='history';navigate('library');break;case 'library-tab':libraryTab=b.dataset.tab;render();break;case 'reset-filters':query='';category='Alle Themen';duration=teacher='all';$('#global-search').value='';render();break;case 'notifications':notifications();break;case 'mark-read':state.read=true;persist();nav();b.textContent='Alles gelesen';break;case 'settings':closeModal();navigate('profile');break;case 'week':week();break;case 'program':programDetail(b.dataset.id);break;case 'enroll':state.program=b.dataset.id;persist();startPlayer(programs.find(p=>p.id===b.dataset.id).ids[0]);break;case 'toggle-play':togglePlayer();break;case 'rewind':if(player){player.current=Math.max(0,player.current-15);updatePlayer();}break;case 'chapter':if(player){player.current=Number(b.dataset.time);updatePlayer();}break;case 'fullscreen':if(document.fullscreenElement)document.exitFullscreen?.();else if($('#player').requestFullscreen)$('#player').requestFullscreen().catch(()=>toast('Vollbild ist in diesem Browser nicht verfügbar.'));else toast('Vollbild ist in diesem Browser nicht verfügbar.');break;}});
document.addEventListener('input',e=>{if(e.target.id==='seek'&&player){player.current=Number(e.target.value);updatePlayer();}if(e.target.id==='course-query'){const start=e.target.selectionStart;query=e.target.value;render();const input=$('#course-query');input.focus();try{input.setSelectionRange(start,start);}catch{}}});
document.addEventListener('change',e=>{if(e.target.id==='category-filter'){category=e.target.value;render();}if(e.target.id==='duration-filter'){duration=e.target.value;render();}if(e.target.id==='teacher-filter'){teacher=e.target.value;render();}});
document.addEventListener('submit',e=>{if(e.target.id==='filters')e.preventDefault();if(e.target.id==='settings-form'){e.preventDefault();const d=new FormData(e.target);state.name=String(d.get('name')||'').trim();state.goal=Number(d.get('goal'));state.reminders=d.get('reminders')==='on';state.time=String(d.get('time'));persist();toast('Deine Einstellungen sind auf diesem Gerät gespeichert.');}});
window.addEventListener('pagehide',()=>{if(player){state.progress[player.id]=Math.min(1,player.current/player.total);persist();}});
render();

if(document.modelContext?.registerTool){
  try{Promise.resolve(document.modelContext.registerTool({name:'search_andavita_courses',description:'Search the demonstration course catalogue. Returns launch series topics; individual lesson labels are draft wording. Does not navigate or change state.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input.query!=='string')throw new Error('query must be a string');return courses.filter(c=>(c.title+' '+c.category+' '+c.teacher).toLowerCase().includes(input.query.toLowerCase())).map(c=>({id:c.id,title:c.title,minutes:c.duration,teacher:c.teacher,demo:true}));}})).catch(()=>{});}catch{}
}
